const action={login:()=>go('home'),signup:()=>{const required=[...app.querySelectorAll('[data-required]')].filter(x=>!x.value.trim()),privacy=app.querySelector('[data-privacy]');required.forEach(x=>x.style.borderColor='#e5484d');if(required.length||!privacy?.checked){if(privacy&&!privacy.checked)privacy.closest('label').style.color='#e5484d';toast(`校验失败：${required.length?'请填写全部必填项':'请确认隐私告知'}`);return}confirm('确认提交报名','请确认姓名、工种、职业等级与联系电话准确，并已同意隐私告知。提交后将进入企业审核。','确认报名')},taskDetail:e=>{const task=e.target.closest('[data-task]')?.dataset.task||'本人任务';const canCheckin=task==='企业初赛签到';openSheet(`<h2>${task}</h2><div class="list"><div><b>任务对象</b><small>李明 · QL260031（本人）</small></div><div><b>所属赛事</b><small>2026 铝行业电解工技能竞赛</small></div><div><b>时间要求</b><small>${canCheckin?'07-10 13:45–14:00 可签到':'以任务列表截止时间为准'}</small></div><div><b>完成条件</b><small>${canCheckin?'完成人脸核验与考前签到':'完成页面所列材料或学习要求'}</small></div></div>${canCheckin?'<div class="actions"><button class="btn" data-close>稍后处理</button><button class="btn primary" data-act="checkin">模拟本人签到</button></div>':'<div class="actions"><button class="btn primary full" data-close>知道了</button></div>'}`)},checkin:()=>openSheet('<h2>签到成功</h2><div class="notice"><b>李明 · QL260031</b><p>已于 2026-07-10 13:48 完成人脸核验与企业初赛签到。</p></div><div class="actions"><button class="btn primary full" data-close>完成</button></div>'),aiOptions:()=>openSheet('<h2>AI 入口候选方案</h2><div class="notice"><b>待业务确认</b><p>无论采用哪种入口，流程知识与专业知识仍需保持权限和知识范围隔离。</p></div><div class="list"><div><b>方案 A：一个统一入口</b><small>由系统识别问题类型并路由到对应知识库，入口简洁，但需清楚展示回答边界与来源。</small></div><div><b>方案 B：两个独立入口</b><small>流程助手负责赛事规则和个人进度，专业知识助手负责赛前学习；边界清楚但入口更多。</small></div></div><div class="actions"><button class="btn primary full" data-close>关闭</button></div>'),startExam:()=>openSheet('<h2>确认开始考试</h2><p>开始后连续计时 90 分钟，仅有 1 次机会；超时自动交卷。</p><div class="actions"><button class="btn" data-close>返回检查</button><button class="btn primary" data-confirm data-next="exam">确认开考</button></div>'),submitExam:()=>confirm('确认交卷','当前已作答 96 题，仍有 4 题未作答。交卷后不可继续作答。','确认交卷'),qnav:()=>openSheet(`<h2>答题卡 · 共 100 题</h2><p class="muted">已作答 96 题，未作答 4 题</p><div class="qnav">${Array.from({length:100},(_,i)=>`<b class="${i<96?'done':''}">${i+1}</b>`).join('')}</div><div class="actions"><button class="btn full" data-close>继续答题</button></div>`),questionType:e=>{examType=Number(e.target.dataset.index);render()},simulateTimeout:()=>go('exam-timeout'),ask:()=>{openSheet('<h2>AI 助手正在回答</h2><p>基于赛事授权知识库检索到 3 条相关内容。回答仅供竞赛学习参考。</p><button class="link" data-act="sourceDetail">查看来源与审计信息</button><div class="actions"><button class="btn primary full" data-close>返回对话</button></div>')},sourceDetail:()=>openSheet('<h2>回答来源详情</h2><div class="notice"><b>竞赛通知第 4 条</b><p>初赛时间与身份核验要求</p></div><div class="notice"><b>企业初赛考务手册 2.1</b><p>考试时长、交卷与异常处理规则</p></div><p class="muted">模型：Qianlv-Assistant-1<br>生成时间：2026-07-10 10:42<br>操作人：李明<br>请求编号：AI-260710-1042</p><div class="actions"><button class="btn primary full" data-close>关闭</button></div>'),messageDetail:()=>openSheet('<h2>消息详情</h2><p>你的企业初赛安排为 7 月 10 日 14:00，请提前 15 分钟完成身份核验。</p><button class="link" data-go="exam-info">查看开考说明</button><div class="actions"><button class="btn full" data-close>关闭</button></div>'),logout:()=>confirm('退出登录','退出后需重新验证手机号。','确认退出'),option:()=>toast('已保存答案')};
