function go(k){location.hash=k}
function render(){const k=location.hash.slice(1)||'login';topbar.innerHTML=k==='login'?'<a href="index.html">← 原型总览</a><span>安全登录</span>':`<b>${({'ai-flow':'流程助手',knowledge:'专业知识助手',exam:'在线初赛','exam-info':'开考说明','exam-timeout':'自动交卷','event-detail':'赛事详情',privacy:'账号与隐私',signup:'竞赛报名',result:'成绩详情',ranking:'排行榜',learning:'在线学习',notices:'通知须知'})[k]||M[k]?.[0]||'竞赛中心'}</b><a href="#notices">通知须知</a>`;app.innerHTML=(pages[k]||pages.home)();tabs.classList.toggle('hidden',k==='login'||k==='exam');document.querySelectorAll('nav button').forEach(x=>x.classList.toggle('active',x.dataset.go===k));}
document.addEventListener('click',e=>{const g=e.target.closest('[data-go]'),a=e.target.closest('[data-act]');if(g){go(g.dataset.go);if(modal.contains(g))modal.classList.remove('show')}if(a)(action[a.dataset.act]||(()=>toast('操作已记录')))(e);if(e.target.closest('[data-close]'))modal.classList.remove('show');const confirmBtn=e.target.closest('[data-confirm]');if(confirmBtn){const next=confirmBtn.dataset.next;modal.classList.remove('show');toast('提交成功');if(next)setTimeout(()=>go(next),300);else if(location.hash==='#signup')setTimeout(()=>go('events'),500);else if(location.hash==='#exam')setTimeout(()=>go('result'),500)}});window.addEventListener('hashchange',render);render();
